import{_ as r,o as a,c as n,a5 as i}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse('{"title":"数组作为方法参数和返回值","description":"","frontmatter":{"title":"数组作为方法参数和返回值","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Java基础","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第一部分：语言基础/02-数组/数组作为方法参数和返回值.md","filePath":"posts/java快速入门/第一部分：语言基础/02-数组/数组作为方法参数和返回值.md"}'),o={name:"posts/java快速入门/第一部分：语言基础/02-数组/数组作为方法参数和返回值.md"};function e(p,t,s,c,d,g){return a(),n("div",null,[...t[0]||(t[0]=[i("<div><p><strong>数组作为方法参数传递，传递的参数是数组内存的地址</strong></p><p>public static void main(String[] args) { int[] arr = { 1, 3, 5, 7, 9 }; // 调用方法，传递数组</p><p>printArray(arr); } /* 创建方法，方法接收数组类型的参数 进行数组的遍历</p><p>*/ public static void printArray(int[] arr) { for (int i = 0; i &lt; arr.length; i++) { System.out.println(arr[i]); } } <strong>数组作为方法返回值</strong> 数组作为方法的返回值，返回的是数组的内存地址</p><p>public static void main(String[] args) { // 调用方法，接收数组的返回值</p><p>// 接收到的是数组的内存地址</p><p>int[] arr = getArray(); for (int i = 0; i &lt; arr.length; i++) { System.out.println(arr[i]); } } /*</p><p>` 创建方法，返回值是数组类型</p><p><code>return</code></p><p>返回数组的地址</p><p>*/ public static int[] getArray() { int[] arr = { 1, 3, 5, 7, 9 }; // 返回数组的地址，返回到调用者</p><p>return arr; } <strong>方法的参数类型区别</strong><strong>代码分析</strong></p><p><code>1.</code></p><p><strong>分析下列程序代码，计算输出结果。</strong></p><p>public static void main(String[] args) { int a = 1; int b = 2; System.out.println(a); System.out.println(b); change(a, b); System.out.println(a); System.out.println(b); } public static void change(int a, int b) { a = a + b; b = b + a; }</p><p><code>2.</code> <strong>分析下列程序代码，计算输出结果。</strong></p><p>public static void main(String[] args) { int[] arr = {1,3,5}; System.out.println(arr[0]); change(arr); System.out.println(arr[0]); } public static void change(int[] arr) { arr[0] = 200; } 总结<code>:</code><strong>方法的参数为基本类型时</strong><code>,</code><strong>传递的是数据值</strong><code>.</code> <strong>方法的参数为引用类型时</strong><code>,</code><strong>传递的是地址值</strong><code>.</code></p></div>",1)])])}const u=r(o,[["render",e]]);export{l as __pageData,u as default};
